package rag

// Shared harness for the default-path tests of RAGService.Retrieve:
// TestRetrieveDefaultGolden (fixed scenarios, checked against a data file that
// was generated by the pre-refactor code) and TestRetrieveMatchesLegacy
// (generated inputs, checked against the frozen copy in retrieval_legacy_test.go).
//
// Everything here uses fake dependencies. A scenario records every observable
// effect of one call: the results (nil and empty are different), the error and
// the sentinels it matches, every call made to the loader, the embedder, both
// searches and the reranker, and the metric counters. Two runs of the same
// scenario are equal exactly when the observable behaviour is equal.

import (
	"GopherAI/common/observability"
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"math"
	"sort"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/cloudwego/eino/components/embedding"
)

var (
	errScenarioEmbed   = errors.New("scenario embedder failure")
	errScenarioVector  = errors.New("scenario vector search failure")
	errScenarioLexical = errors.New("scenario lexical search failure")
	errScenarioLoad    = errors.New("scenario document loader failure")
	errScenarioRerank  = errors.New("scenario reranker failure")
)

type embedMode int

const (
	embedOK embedMode = iota
	embedError
	embedCanceled // returns an error wrapping context.Canceled whatever the context says
	embedWrongCount
	embedWrongDim
	embedNaN
	embedWait // blocks until the context ends
)

type rerankMode string

const (
	rerankNone        rerankMode = ""
	rerankReverse     rerankMode = "reverse"     // later candidates score higher
	rerankTie         rerankMode = "tie"         // every candidate has the same score
	rerankMixed       rerankMode = "mixed"       // repeating scores with ties
	rerankUnavailable rerankMode = "unavailable" // ErrRerankUnavailable
	rerankFailure     rerankMode = "failure"     // any other error
	rerankShort       rerankMode = "short"       // one score too few
	rerankBadIndex    rerankMode = "bad-index"   // an index outside the candidate list
	rerankDupIndex    rerankMode = "dup-index"   // the same index twice
	rerankNaN         rerankMode = "nan"         // a NaN score
)

type retrievalScenario struct {
	Name       string
	UserID     int64
	Query      string
	TopK       int
	Active     []ActiveDocument
	ActiveErr  error
	Vector     []RedisChunkSearchResult
	Lexical    []RedisChunkSearchResult
	VectorErr  error
	LexicalErr error
	Embed      embedMode
	Rerank     rerankMode
	Timeout    time.Duration
	PreCancel  bool
	NilContext bool
}

type retrievalSearchCall struct {
	UserID int64    `json:"user_id"`
	Query  string   `json:"query,omitempty"`
	TopK   int      `json:"top_k"`
	Active []string `json:"active"`
}

type retrievalRerankCall struct {
	Query    string   `json:"query"`
	Passages []string `json:"passages"`
}

// retrievalRecord is everything observable about one call.
type retrievalRecord struct {
	Results      []RetrievalResult
	Err          string
	ErrKinds     []string
	Reason       string
	Loads        []int64
	EmbedCalls   [][]string
	VectorCalls  []retrievalSearchCall
	LexicalCalls []retrievalSearchCall
	RerankCalls  []retrievalRerankCall
	Counters     map[string]uint64
}

type retrievalCallLog struct {
	mu           sync.Mutex
	loads        []int64
	embedCalls   [][]string
	vectorCalls  []retrievalSearchCall
	lexicalCalls []retrievalSearchCall
	rerankCalls  []retrievalRerankCall
}

type recordingEmbedder struct {
	mode embedMode
	log  *retrievalCallLog
}

func (e *recordingEmbedder) EmbedStrings(ctx context.Context, texts []string, _ ...embedding.Option) ([][]float64, error) {
	e.log.mu.Lock()
	e.log.embedCalls = append(e.log.embedCalls, append([]string(nil), texts...))
	e.log.mu.Unlock()
	switch e.mode {
	case embedError:
		return nil, errScenarioEmbed
	case embedCanceled:
		return nil, fmt.Errorf("wrapped embedder: %w", context.Canceled)
	case embedWait:
		<-ctx.Done()
		return nil, ctx.Err()
	case embedWrongCount:
		return [][]float64{{1, 0, 0, 0}, {0, 1, 0, 0}}, nil
	case embedWrongDim:
		return [][]float64{{1, 0, 0}}, nil
	case embedNaN:
		return [][]float64{{math.NaN(), 0, 0, 0}}, nil
	}
	vectors := make([][]float64, len(texts))
	for index := range vectors {
		vectors[index] = []float64{1, 0, 0, 0}
	}
	return vectors, nil
}

type recordingSearcher struct {
	vector, lexical       []RedisChunkSearchResult
	vectorErr, lexicalErr error
	log                   *retrievalCallLog
}

func (s *recordingSearcher) EnsureIndex(context.Context) error { return nil }

func activeAsStrings(active map[string]int) []string {
	out := make([]string, 0, len(active))
	for id, version := range active {
		out = append(out, fmt.Sprintf("%s=%d", id, version))
	}
	sort.Strings(out)
	return out
}

func truncateRows(rows []RedisChunkSearchResult, topK int) []RedisChunkSearchResult {
	if topK < len(rows) {
		rows = rows[:topK]
	}
	return append([]RedisChunkSearchResult(nil), rows...)
}

func (s *recordingSearcher) SearchActiveByUserVector(_ context.Context, userID int64, _ []float32, topK int, active map[string]int) ([]RedisChunkSearchResult, error) {
	s.log.mu.Lock()
	s.log.vectorCalls = append(s.log.vectorCalls, retrievalSearchCall{UserID: userID, TopK: topK, Active: activeAsStrings(active)})
	s.log.mu.Unlock()
	if s.vectorErr != nil {
		return nil, s.vectorErr
	}
	return truncateRows(s.vector, topK), nil
}

func (s *recordingSearcher) SearchActiveByUserText(_ context.Context, userID int64, query string, topK int, active map[string]int) ([]RedisChunkSearchResult, error) {
	s.log.mu.Lock()
	s.log.lexicalCalls = append(s.log.lexicalCalls, retrievalSearchCall{UserID: userID, Query: query, TopK: topK, Active: activeAsStrings(active)})
	s.log.mu.Unlock()
	if s.lexicalErr != nil {
		return nil, s.lexicalErr
	}
	return truncateRows(s.lexical, topK), nil
}

type recordingReranker struct {
	mode rerankMode
	log  *retrievalCallLog
}

func (r *recordingReranker) Health(context.Context) error { return nil }

func (r *recordingReranker) Rerank(_ context.Context, query string, passages []string) ([]RerankScore, error) {
	r.log.mu.Lock()
	r.log.rerankCalls = append(r.log.rerankCalls, retrievalRerankCall{Query: query, Passages: append([]string(nil), passages...)})
	r.log.mu.Unlock()
	count := len(passages)
	scores := make([]RerankScore, 0, count)
	switch r.mode {
	case rerankUnavailable:
		return nil, fmt.Errorf("%w: scenario unavailable", ErrRerankUnavailable)
	case rerankFailure:
		return nil, errScenarioRerank
	}
	for index := count - 1; index >= 0; index-- { // returned in reverse so the service's own sort is exercised
		score := float64(index) * 0.5
		switch r.mode {
		case rerankTie:
			score = 1
		case rerankMixed:
			score = float64((index * 7) % 5)
		}
		scores = append(scores, RerankScore{Index: index, Score: score})
	}
	switch r.mode {
	case rerankShort:
		if len(scores) > 0 {
			scores = scores[1:]
		}
	case rerankBadIndex:
		if len(scores) > 0 {
			scores[0].Index = count
		}
	case rerankDupIndex:
		if len(scores) > 1 {
			scores[1].Index = scores[0].Index
		}
	case rerankNaN:
		if len(scores) > 0 {
			scores[0].Score = math.NaN()
		}
	}
	return scores, nil
}

// rowFlags shape generated candidate rows.
type rowFlags struct {
	noKeyEvery   int // every Nth row has no RedisKey (identity falls back to DocID:ChunkID)
	noEmbedEvery int // every Nth row has empty EmbeddingContent (rerank falls back to RawContent)
	emptyContent bool
	staleEvery   int // every Nth row names a version that is not the active one
}

func scenarioRow(n, docs int, flags rowFlags) RedisChunkSearchResult {
	doc := n % docs
	row := RedisChunkSearchResult{
		ExecutionID: fmt.Sprintf("exec-%d", n%4),
		RedisKey:    fmt.Sprintf("key-%d", n), ChunkID: fmt.Sprintf("chunk-%d", n),
		DocID: fmt.Sprintf("doc-%d", doc), DocVersion: doc + 1,
		ChunkIndex: n, ChunkType: "prose", SourceFile: fmt.Sprintf("file-%d.md", doc),
		TitlePath: fmt.Sprintf("Title %d > Section %d", doc, n%5), StartLine: n*10 + 1, EndLine: n*10 + 9,
		RawContent: fmt.Sprintf("raw content %d", n), EmbeddingContent: fmt.Sprintf("embedding content %d", n),
		ContentHash: fmt.Sprintf("hash-%d", n), CodeLanguage: "go", Symbols: "SymA SymB", TokenEstimate: 10 + n,
		PartIndex: n % 3, PartTotal: 3,
		Distance: float64(n)/200 + 0.01, LexicalScore: 100 - float64(n)/3,
	}
	if flags.noKeyEvery > 0 && n%flags.noKeyEvery == 0 {
		row.RedisKey = ""
	}
	if flags.noEmbedEvery > 0 && n%flags.noEmbedEvery == 0 {
		row.EmbeddingContent = ""
	}
	if flags.emptyContent {
		row.EmbeddingContent, row.RawContent = "", ""
	}
	if flags.staleEvery > 0 && n%flags.staleEvery == 0 {
		row.DocVersion += 10
	}
	return row
}

// scenarioRows builds count rows numbered from first. Rows with the same number
// in two channels are the same chunk, which is how overlap is expressed.
func scenarioRows(first, count, docs int, flags rowFlags) []RedisChunkSearchResult {
	rows := make([]RedisChunkSearchResult, 0, count)
	for n := first; n < first+count; n++ {
		rows = append(rows, scenarioRow(n, docs, flags))
	}
	return rows
}

func scenarioActive(docs int) []ActiveDocument {
	active := make([]ActiveDocument, 0, docs)
	for doc := 0; doc < docs; doc++ {
		active = append(active, ActiveDocument{DocID: fmt.Sprintf("doc-%d", doc), Version: doc + 1, OriginalName: fmt.Sprintf("file-%d.md", doc)})
	}
	return active
}

type retrievalCall func(*RAGService, context.Context, int64, string, int) ([]RetrievalResult, error)

func currentRetrieve(s *RAGService, ctx context.Context, userID int64, query string, topK int) ([]RetrievalResult, error) {
	return s.Retrieve(ctx, userID, query, topK)
}

var retrievalErrorSentinels = []struct {
	name   string
	target error
}{
	{"invalid_request", ErrInvalidRetrievalRequest},
	{"unavailable", ErrRetrievalUnavailable},
	{"failed", ErrRetrievalFailed},
	{"rerank_unavailable", ErrRerankUnavailable},
	{"context_canceled", context.Canceled},
	{"context_deadline", context.DeadlineExceeded},
	{"scenario_embed", errScenarioEmbed},
	{"scenario_vector", errScenarioVector},
	{"scenario_lexical", errScenarioLexical},
	{"scenario_load", errScenarioLoad},
	{"scenario_rerank", errScenarioRerank},
}

// runRetrievalScenario builds fresh fakes, runs one call through `call` and
// returns every observable effect.
func runRetrievalScenario(t testing.TB, sc retrievalScenario, call retrievalCall) retrievalRecord {
	t.Helper()
	log := &retrievalCallLog{}
	loader := func(_ context.Context, userID int64) ([]ActiveDocument, error) {
		log.mu.Lock()
		log.loads = append(log.loads, userID)
		log.mu.Unlock()
		if sc.ActiveErr != nil {
			return nil, sc.ActiveErr
		}
		return append([]ActiveDocument(nil), sc.Active...), nil
	}
	searcher := &recordingSearcher{vector: sc.Vector, lexical: sc.Lexical, vectorErr: sc.VectorErr, lexicalErr: sc.LexicalErr, log: log}
	service, err := NewRAGService(context.Background(), &recordingEmbedder{mode: sc.Embed, log: log}, searcher, loader, 4)
	if err != nil {
		t.Fatalf("scenario %q: build service: %v", sc.Name, err)
	}
	if sc.Rerank != rerankNone {
		if err := service.UseReranker(context.Background(), &recordingReranker{mode: sc.Rerank, log: log}); err != nil {
			t.Fatalf("scenario %q: attach reranker: %v", sc.Name, err)
		}
	}
	if sc.Timeout > 0 {
		service.timeout = sc.Timeout
	}
	previous := observability.Memory
	recorder := observability.NewMemoryRecorder(nil)
	observability.Memory = recorder
	defer func() { observability.Memory = previous }()

	var ctx context.Context
	switch {
	case sc.NilContext:
		ctx = nil //nolint:staticcheck // Retrieve accepts a nil context and replaces it
	case sc.PreCancel:
		cancelled, cancel := context.WithCancel(context.Background())
		cancel()
		ctx = cancelled
	default:
		ctx = context.Background()
	}
	results, callErr := call(service, ctx, sc.UserID, sc.Query, sc.TopK)

	record := retrievalRecord{Results: results, Counters: map[string]uint64{}}
	if callErr != nil {
		record.Err = callErr.Error()
		for _, sentinel := range retrievalErrorSentinels {
			if errors.Is(callErr, sentinel.target) {
				record.ErrKinds = append(record.ErrKinds, sentinel.name)
			}
		}
		if reason, ok := RetrievalUnavailableReasonOf(callErr); ok {
			record.Reason = string(reason)
		}
	}
	for key, value := range recorder.Snapshot().Counters {
		record.Counters[key] = value
	}
	log.mu.Lock()
	defer log.mu.Unlock()
	record.Loads = append([]int64(nil), log.loads...)
	record.EmbedCalls = append([][]string(nil), log.embedCalls...)
	record.VectorCalls = append([]retrievalSearchCall(nil), log.vectorCalls...)
	record.LexicalCalls = append([]retrievalSearchCall(nil), log.lexicalCalls...)
	record.RerankCalls = append([]retrievalRerankCall(nil), log.rerankCalls...)
	return record
}

// retrievalGoldenRecord is the reviewable form of a record that is stored in
// testdata/retrieve_default.golden.json.
type retrievalGoldenRecord struct {
	Name          string                `json:"name"`
	ResultsNil    bool                  `json:"results_nil"`
	ResultCount   int                   `json:"result_count"`
	Results       []string              `json:"results"`
	ResultsSHA256 string                `json:"results_sha256"`
	ExecutionIDs  []string              `json:"execution_ids"`
	Error         string                `json:"error"`
	ErrorKinds    []string              `json:"error_kinds"`
	Reason        string                `json:"reason"`
	Loads         []int64               `json:"loader_user_ids"`
	EmbedCalls    [][]string            `json:"embed_calls"`
	VectorCalls   []retrievalSearchCall `json:"vector_calls"`
	LexicalCalls  []retrievalSearchCall `json:"lexical_calls"`
	RerankCalls   []retrievalRerankCall `json:"rerank_calls"`
	Counters      map[string]uint64     `json:"counters"`
}

func (r retrievalRecord) golden(name string) retrievalGoldenRecord {
	fullJSON, _ := json.Marshal(r.Results) // nil marshals to null, empty to []
	sum := sha256.Sum256(fullJSON)
	summary := make([]string, 0, len(r.Results))
	executionIDs := make([]string, 0, len(r.Results))
	for _, result := range r.Results {
		summary = append(summary, fmt.Sprintf("%s|%s|v%d|l%d|r%d|%t|%.6f|%.6f", result.ChunkID, result.MatchKind,
			result.VectorRank, result.LexicalRank, result.RerankRank, result.RerankApplied, result.Score, result.RerankScore))
		executionIDs = append(executionIDs, result.ExecutionID)
	}
	record := retrievalGoldenRecord{
		Name: name, ResultsNil: r.Results == nil, ResultCount: len(r.Results), Results: summary,
		ResultsSHA256: hex.EncodeToString(sum[:]), ExecutionIDs: executionIDs,
		Error: r.Err, ErrorKinds: r.ErrKinds, Reason: r.Reason, Loads: r.Loads, EmbedCalls: r.EmbedCalls,
		VectorCalls: r.VectorCalls, LexicalCalls: r.LexicalCalls, RerankCalls: r.RerankCalls, Counters: r.Counters,
	}
	// Normalise nil slices so the JSON never distinguishes "no calls" from "no calls".
	if record.ErrorKinds == nil {
		record.ErrorKinds = []string{}
	}
	if record.Loads == nil {
		record.Loads = []int64{}
	}
	if record.EmbedCalls == nil {
		record.EmbedCalls = [][]string{}
	}
	if record.VectorCalls == nil {
		record.VectorCalls = []retrievalSearchCall{}
	}
	if record.LexicalCalls == nil {
		record.LexicalCalls = []retrievalSearchCall{}
	}
	if record.RerankCalls == nil {
		record.RerankCalls = []retrievalRerankCall{}
	}
	return record
}

func jsonIndent(value any) (string, error) {
	data, err := json.MarshalIndent(value, "", "  ")
	return string(data), err
}

func describeScenario(sc retrievalScenario) string {
	return fmt.Sprintf("%s (user=%d query=%q topK=%d active=%d vector=%d lexical=%d embed=%d rerank=%q timeout=%s precancel=%t nilctx=%t)",
		sc.Name, sc.UserID, strings.TrimSpace(sc.Query), sc.TopK, len(sc.Active), len(sc.Vector), len(sc.Lexical), sc.Embed, sc.Rerank,
		sc.Timeout, sc.PreCancel, sc.NilContext)
}
